x, y, d = 0, 0, 0
steps = [('left', 0), ('forward', 2), ('forward', 2), ('right', 0), ('forward', 3), ('left', 0), ('forward', 4), ('forward', 4), ('forward', 4), ('forward', 3)]
for act, n in steps:
    if act == 'forward':
        dx, dy = move[dirs[d]]
        x, y = x + dx * n, y + dy * n
    elif act == 'left':
        d = (d - 1) % 4
    elif act == 'right':
        d = (d + 1) % 4
print((x, y))
```

