steps = [('left', 0), ('left', 0), ('forward', 1), ('forward', 3), ('forward', 3), ('left', 0), ('right', 0), ('forward', 3), ('left', 0), ('forward', 2)]
for act, n in steps:
    if act == 'forward':
        dx, dy = move[dirs[d]]
        x, y = x + dx * n, y + dy * n
    elif act == 'left':
        d = (d - 1) % 4
    elif act == 'right':
        d = (d + 1) % 4
print((x, y))
```

