steps = [('left', 3), ('left', 3), ('left', 3), ('right', 4), ('forward', 1), ('right', 3), ('right', 3), ('right', 3), ('right', 4), ('forward', 1)]
for act, n in steps:
    if act == 'forward':
        dx, dy = move[dirs[d]]
        x, y = x + dx * n, y + dy * n
    elif act == 'left':
        d = (d - 1) % 4
    elif act == 'right':
        d = (d + 1) % 4
print((x, y))
```

